const b = $('Datei vom Listener-Bot').item.json.body;
const mime = String(b.mimetype || '').toLowerCase();
const name = String(b.filename || 'beleg');
const ext = (name.split('.').pop() || '').toLowerCase();
const istPdf = mime === 'application/pdf' || ext === 'pdf';
const istXml = ['application/xml', 'text/xml'].includes(mime) || ext === 'xml';
const ok = (istPdf || istXml) && !!b.data_base64;
const endung = istXml ? 'xml' : 'pdf';
const jetzt = new Date();
const stamp = jetzt.toISOString().slice(0, 19).replace('T', '_').replace(/:/g, '-');
const zufall = Math.random().toString(36).substring(2, 6);
const stagingFileName = `${stamp}_ally-chat_${zufall}.${endung}`;
// Ablage im Eingang der Belege über SPEICHER 1 (Bereich ally, Server oder eigener Speicherort)
const datei_pfad = 'Belegerfassung/Belege-Staging/' + stagingFileName;
const out = {
  json: {
    event_id: b.event_id, room_id: b.room_id, sender: b.sender,
    dateiname: name, mimetype: mime, beschriftung: b.caption || '',
    ok, stagingFileName,
    datei_bereich: 'ally', datei_pfad,
    aktion: 'ablegen', bereich: 'ally', pfad: datei_pfad, ueberschreiben: false
  }
};
if (ok) {
  out.binary = { datei: await this.helpers.prepareBinaryData(Buffer.from(b.data_base64, 'base64'), stagingFileName, istXml ? 'application/xml' : 'application/pdf') };
}
return out;

